"""Stream replay engine for the CrossCheck wire contract.

One stream owns independent measured inputs, a routing plan, frozen repair
snapshots and a process-local repair cache.  Events are replayed strictly in
order: sparse patches are atomic, route events replace the whole plan, repairs
publish a deterministic certificate and validation compares frozen
publications with current expectations.
"""

import json
import sys
from hashlib import sha256

from .common_utils import MAX_DEMAND, Topology
from .dtp import compute_repair
from .snapshot_cache import RepairCache, SnapshotStore
from .validate import validate_snapshot

CELL_ANNOTATIONS = frozenset(("ground_truth", "corrected", "confidence"))
PATCH_FIELDS = frozenset(("op", "demands", "counters"))


class DomainError(Exception):
    """Raised for requests outside the replay domain."""


def integer(value):
    """Schema integer: booleans are not integers anywhere in this schema."""
    if value is True or value is False:
        raise DomainError("boolean is not an integer")
    if not isinstance(value, int):
        raise DomainError("expected an integer")
    return value


def fraction(value):
    """A nonnegative reduced-or-not fraction given as ``[numerator, denominator]``."""
    if not isinstance(value, list) or len(value) != 2:
        raise DomainError("expected a fraction pair")
    numerator = integer(value[0])
    denominator = integer(value[1])
    if denominator <= 0:
        raise DomainError("fraction denominator must be positive")
    if numerator < 0:
        raise DomainError("fraction numerator must be nonnegative")
    return numerator, denominator


class Settings:
    """Fixed per-stream settings; validation settings never affect repairs."""

    __slots__ = ("trials", "epsilon", "seed", "cutoff_numerator", "cutoff_denominator",
                 "bias", "tau", "gamma_numerator", "gamma_denominator", "cache_slots")

    def __init__(self, spec):
        self.trials = integer(spec["trials"])
        self.epsilon = integer(spec["epsilon"])
        self.seed = integer(spec["seed"])
        self.cutoff_numerator, self.cutoff_denominator = fraction(spec["cutoff"])
        self.bias = integer(spec["bias"])
        self.tau = integer(spec["tau"])
        self.gamma_numerator, self.gamma_denominator = fraction(spec["gamma"])
        self.cache_slots = integer(spec["cache_slots"])


class StreamState:
    """Persistent measured inputs and the active routing plan."""

    __slots__ = ("counters", "demands", "routes", "routes_identity")

    def __init__(self):
        self.counters = {}
        self.demands = {}
        self.routes = None
        self.routes_identity = None

    def normalized_counters(self):
        return tuple((key, self.counters.get(key)) for key in self.topology_keys)

    def normalized_demands(self, pairs):
        demands = self.demands
        return tuple((pair, demands.get(pair, 0)) for pair in pairs)


def parse_routes(topology, paths):
    """Parse a routing plan into ``(plan, canonical_identity)``.

    The identity is the multiset of weighted path entries for every ordered
    external pair, so splitting or merging entries changes the key while plan,
    object and bundle order never do.
    """
    if paths is None:
        return None, None
    id_of_name = topology.id_of_name
    plan = {}
    identity = []
    for source_name, bundles in paths.items():
        source = id_of_name[source_name]
        for target_name, entries in bundles.items():
            target = id_of_name[target_name]
            parsed = []
            for entry in entries:
                path = tuple(id_of_name[name] for name in entry["path"])
                parsed.append((path, integer(entry["weight"])))
            parsed.sort()
            plan[(source, target)] = parsed
            identity.append((source, target, tuple(parsed)))
    identity.sort()
    return plan, tuple(identity)


def build_repair_answer(result, identifier, cache_hit):
    links, order, counters = result
    return {
        "op": "repair",
        "id": identifier,
        "cache_hit": cache_hit,
        "links": [[source, target, value, numerator, denominator]
                  for source, target, value, numerator, denominator in links],
        "order": [[source, target] for source, target in order],
        "counters": {key: {"corrected": value, "confidence": [numerator, denominator]}
                     for key, value, numerator, denominator in counters},
    }


class StreamEngine:
    """Replays one stream of events over independent state."""

    def __init__(self, stream):
        self.topology = Topology(stream["topology"])
        self.settings = Settings(stream["settings"])
        self.state = StreamState()
        self.snapshots = SnapshotStore()
        self.cache = RepairCache(self.settings.cache_slots)

    def replay(self, events):
        return [self.handle(event) for event in events]

    def handle(self, event):
        try:
            if not isinstance(event, dict):
                raise DomainError("event must be an object")
            operation = event.get("op")
            if operation == "patch":
                return self.do_patch(event)
            if operation == "routes":
                return self.do_routes(event)
            if operation == "repair":
                return self.do_repair(event)
            if operation == "validate":
                return self.do_validate(event)
            raise DomainError("unknown operation")
        except Exception as error:  # noqa: BLE001 - one odd event cannot end the replay
            sys.stderr.write('event fallback: %r\n' % (error,))
            return self.fallback(event)

    @staticmethod
    def fallback(event):
        operation = event.get("op") if isinstance(event, dict) else None
        if operation == "patch":
            return {"op": "patch", "accepted": False}
        if operation == "routes":
            return {"op": "routes", "accepted": False}
        if operation == "repair" or operation == "validate":
            identifier = event.get("id") if isinstance(event, dict) else None
            if operation == "repair":
                return {"op": "repair", "id": identifier, "cache_hit": False,
                        "links": [], "order": [], "counters": {}}
            return {"op": "validate", "id": identifier, "checked": 0, "passed": 0,
                    "consistent": None, "failed": []}
        return {"op": operation} if isinstance(operation, str) else {}

    # ------------------------------------------------------------------ patch
    def do_patch(self, event):
        reject = {"op": "patch", "accepted": False}
        if len(event) != 3 or not PATCH_FIELDS.issubset(event):
            return reject
        demands = event["demands"]
        counters = event["counters"]
        if not isinstance(demands, list) or not isinstance(counters, dict):
            return reject
        topology = self.topology
        external = topology.external_ids
        demand_updates = {}
        for entry in demands:
            if not isinstance(entry, list) or len(entry) != 3:
                return reject
            try:
                source = integer(entry[0])
                target = integer(entry[1])
                value = integer(entry[2])
            except DomainError:
                return reject
            if source == target or source not in external or target not in external:
                return reject
            pair = (source, target)
            if pair in demand_updates:
                return reject
            if value < 0 or value > MAX_DEMAND:
                return reject
            demand_updates[pair] = value
        counter_updates = {}
        for key, cell in counters.items():
            flow = topology.key_flow.get(key)
            if flow is None:
                return reject
            if cell is None:
                counter_updates[key] = None
                continue
            if not isinstance(cell, dict) or "perturbed" not in cell:
                return reject
            if len(cell) > 1 + len(CELL_ANNOTATIONS):
                return reject
            for name in cell:
                if name != "perturbed" and name not in CELL_ANNOTATIONS:
                    return reject
            perturbed = cell["perturbed"]
            if perturbed is not None:
                try:
                    perturbed = integer(perturbed)
                except DomainError:
                    return reject
                if perturbed < 0 or perturbed > topology.flow_cap[flow]:
                    return reject
            counter_updates[key] = perturbed
        # Both containers apply atomically or not at all.
        self.state.demands.update(demand_updates)
        for key, value in counter_updates.items():
            if value is None:
                self.state.counters.pop(key, None)
            else:
                self.state.counters[key] = value
        return {"op": "patch", "accepted": True}

    # ----------------------------------------------------------------- routes
    def do_routes(self, event):
        paths = event["paths"]
        plan, identity = parse_routes(self.topology, paths)
        self.state.routes = plan
        self.state.routes_identity = identity
        return {"op": "routes", "accepted": True}

    # ----------------------------------------------------------------- repair
    def do_repair(self, event):
        identifier = event["id"]
        key = self.cache_key()
        result = self.cache.lookup(key)
        if result is not None:
            cache_hit = True
        else:
            result = compute_repair(self.topology, self.state.counters, self.state.demands,
                                    self.state.routes, self.settings)
            self.cache.insert(key, result)
            cache_hit = False
        self.snapshots.freeze(identifier, result)
        return build_repair_answer(result, identifier, cache_hit)

    # --------------------------------------------------------------- validate
    def do_validate(self, event):
        identifier = event["id"]
        snapshot = self.snapshots.get(identifier)
        if snapshot is None:
            raise DomainError("unknown snapshot")
        return validate_snapshot(self.topology, self.state, self.settings, snapshot, identifier)

    # ------------------------------------------------------------ memoization
    def cache_key(self):
        """Semantic identity of the next repair.

        Labels, ignored annotations, input order, snapshot identifiers and
        validation settings are not identities; measured inputs are normalized
        so that explicit zeros and missing reports compare with their
        implicit defaults.
        """
        state = self.state
        topology = self.topology
        counters = state.counters
        demands = state.demands
        payload = json.dumps(
            (topology.canonical,
             tuple((key, counters.get(key)) for key in topology.all_keys),
             tuple((pair, demands.get(pair, 0)) for pair in topology.external_pairs),
             state.routes_identity,
             (self.settings.seed, self.settings.trials, self.settings.epsilon)),
            separators=(",", ":"), sort_keys=True, allow_nan=False)
        return sha256(payload.encode("utf-8")).hexdigest()


def run_request(request):
    """Replay every stream of one request and return the wire answer."""
    if not isinstance(request, dict):
        raise DomainError("request must be an object")
    streams = request["streams"]
    if not isinstance(streams, list):
        raise DomainError("streams must be an array")
    answers = []
    for stream in streams:
        engine = StreamEngine(stream)
        answers.append({"events": engine.replay(stream["events"])})
    return {"streams": answers}
